/** Lookup helper used by the example normalizer. */
export function getSwedishExampleOverride(sv: string): SwedishExampleOverride | undefined {
  const key = (sv || "").toLowerCase().trim();
  return SWEDISH_EXAMPLE_OVERRIDES[key];
}
